#pragma warning disable
namespace OrbitalMod;

/// <summary>
/// The map's own icons (KSP's maneuver symbols), white PNGs embedded here and tinted when drawn.
/// Loaded the way the game loads banners and thumbnails: the file is written to the game's Temp
/// folder and handed to its RuntimeGUIAssetService, which gives a texture for DrawImage.
/// </summary>
public static class MapIcons
{
    static readonly Dictionary<string, string> Png = new Dictionary<string, string>
    {
        { "prograde", "" },
        { "retrograde", "" },
        { "normal", "" },
        { "antinormal", "" },
        { "radialout", "" },
        { "radialin", "" },
        { "node", "" },
    };
    // Kept alive while in use (disposing one unloads its texture).
    static readonly Dictionary<string, Keen.Game2.Client.UI.Library.RuntimeGUIAsset> _assets = new Dictionary<string, Keen.Game2.Client.UI.Library.RuntimeGUIAsset>();
    public static string Status = "-";

    public static bool Has(string name) => Png.ContainsKey(name);

    /// <summary>The texture for one of our icons (a boxed ResourceHandle), or null.</summary>
    public static object Handle(string name)
    {
        try
        {
            if (!_assets.TryGetValue(name, out var a))
            {
                if (!Png.TryGetValue(name, out var b64)) return null;
                byte[] png = Convert.FromBase64String(b64);
                var fh = new Keen.VRage.Library.Filesystem.FileHandleWritable(Keen.VRage.Library.Filesystem.RootPath.Temp, "OrbitalMod/icons/" + name + ".png");
                fh.CreateDirectories();
                using (var st = fh.Open(System.IO.FileMode.Create, System.IO.FileAccess.Write, System.IO.FileShare.None)) st.Write(png, 0, png.Length);
                a = Keen.Game2.Client.UI.Library.RuntimeGUIAssetService.Instance.GetAsset(fh);
                _assets[name] = a;
            }
            if (a == null) return null;
            Keen.VRage.Library.Utils.ResourceHandle h = a.Asset;
            return h;
        }
        catch (Exception e) { Status = name + ": " + e.Message; return null; }
    }
}
